head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.secugrpId = "";       // 증권그룹ID SR·SW — 원본 fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID())
scwin.isurCd = "";          // 발행회사코드 — 종목 찾기 결과 (원본 vIsurCd)
scwin.mktTpCd = "";         // 종목 시장구분 1: 유가, 2: 코스닥 — 종목 찾기 결과 (원본 vSPOT_ISU_TRD_MKT_TP_CD)
scwin.bzProcsNo = "";       // 업무처리번호 — 이력에서 고른 건, 비면 신규 (원본 vBzProcsNo)
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제 (원본 trsIdx)
scwin.savedState = "";      // 상세를 채운 직후의 값 — 안내문작성 전 변경 여부 판정용 (원본 dts_Mst.IsUpdated)
scwin.MENU_CD_SW = "05707";                 // 신주인수권증권(SW) 메뉴 코드 끝자리 — 그 밖은 신주인수권증서(SR). TODO: TO-BE 메뉴 코드 체계 확인 (§10 #6)
scwin.RSNCD_DELIST = "4";                   // 사유 찾기 구분 — 상장폐지사유 (pcc list_common RSNCD_DELIST)
// 원본 : /lstproc/ULDSTF05806.gfm (상장폐지 — 메뉴 STF05806 신주인수권증서, STF05707 신주인수권증권이 같은 API 를 쓴다)
/*
 * 화면 동작
 *  - [종목 찾기](ULDSTF92017)로 종목을 고르면 그 종목 시장(유가 1 / 코스닥 2)에 맞게 입력 방식을 바꾸고
 *    총주식수(상장증권수)와 상장폐지 이력을 조회해 신규 입력 상태가 된다.
 *  - 유가는 상장폐지사유를 찾기(ULDSTF92008)로 고르고 예고기간·정리매매 허용기간을 쓴다. 코스닥은 사유를 직접 입력하고 두 기간을 숨긴다.
 *  - 이력 행을 누르면 그 건을 상세로 읽고, 상장폐지일이 오늘 이후(오늘 포함)면 수정·삭제·기안·안내문작성, 지났으면 기안만 할 수 있다.
 *  - [저장]은 검증 → 업무 중복 확인 → 확인 → 등록(업무처리번호는 서버 채번), [수정]·[삭제]는 확인 뒤 처리한다.
 *    성공하면 다시 조회하고, 저장·수정이면 그 건을 다시 상세로 읽는다.
 *  - 공시안내문작성(ULDSTF92024)·기안(ULDSTF92004)은 openPopup 의 data 로 넘기고 await 한다.
 *    92024 전환본이 아직 부모 getPar 를 부르므로 호환용 scwin.getPar 만 임시로 둔다(§10 #8).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF05806/ULDSTF05806.md (§번호는 이 문서의 절)
 */

// 고정값
scwin.DSCL_FORM_CD = {                      // 공시안내문 서식코드 — 시장구분 → 증권그룹 (원본 fn_dscl 의 arr[0])
    "1" : { SW : "68913", SR : "68917" },   // 유가
    "2" : { SW : "70925", SR : "70930" }    // 코스닥
};
scwin.JOB_NM = { I : "저장", U : "수정", D : "삭제" };

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    draft : "btn_Drft",         // [기안]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 29
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05806.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 29
 * @description 로딩 — 증권그룹ID·상장증권수(증서수) 라벨 → 버튼 신규 상태 → 사용자 시장별 입력 방식 → 달력·조회 Enter 키 바인딩.
 * 초기 조회는 없다(종목을 골라야 조회). (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 증권그룹ID — 메뉴로 정한다(원본 fn_getSecuGrpId(InfoMenuID())). 라벨·그리드 머리글도 여기서 한 번 정한다(원본 fn_list_sync 앞부분)
    scwin.secugrpId = scwin.getSecugrpId();
    scwin.setSecugrpLabel();

    // 2) 버튼 — 신규 상태(저장만 활성). 원본 buttonSet.setSaveInfo/…/setDrftInfo + setInsertStatus
    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);

    // 3) 사용자 시장별 입력 방식 — 원본 fn_initMktPerComponent(js_market)
    scwin.setComponentByMkt(String($c.session.getUserInfo("market") ?? ""));

    // 4) 달력 검사 바인딩(1회) — 단일 달력은 checkCalendarFormat, 기간 쌍은 compareFromToDate 만(규칙 37) · 조회 영역 Enter 키(규칙 22)
    $c.date.checkCalendarFormat(edt_DELIST_DD, "yyyyMMdd");
    $c.date.compareFromToDate(edt_DELIST_ADVNOTI_STRT_DD, edt_DELIST_ADVNOTI_END_DD, ["상장폐지예고 시작일", "상장폐지예고 종료일"]);
    $c.date.compareFromToDate(edt_ARRANTRD_MKTACT_ENFORCE_DD, edt_ARRANTRD_END_DD, ["정리매매허용 시작일", "정리매매허용 종료일"]);
    $c.win.setEnterKeyEvent(panel_Top, scwin.btn_Search_onclick);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 조회 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05806.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_ISU_NM_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목 찾기(돋보기) 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_ISU_NM_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05806.img_ISU_NM_onclick" });
