        await scwin.openRsnPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05806.img_DELIST_RSN_DSC_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_List_oncellclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장폐지 이력 행 클릭 — 그 건을 상세로 읽는다. (원본 grd_List OnClick → fn_read_sync)
 * @param {Number} rowIndex 행 인덱스(화면 번호)
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns
 * @hidden N
 */
scwin.grd_List_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.selectDetail(String(dlt_list.getCellData(rowIndex, "bzProcsNo") ?? ""));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05806.grd_List_oncellclick" });
    }
};

