///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectTotStkCnt
 * @author Inswave
 * @date 2026. 10. 29
 * @description 총주식수 조회 — 응답의 액면가·상장증권수를 상세에 넣는다. (원본 fn_isubook_read_sync — §5.1)
 * @returns
 * @hidden N
 */
scwin.selectTotStkCnt = async function () {
    const sbmOptions = {
        id : "sbm_selectTotStkCnt",
        method : "get",
        action : "/api/listing/lstproc/warrant/delisting/select-totstkcnt",
        target : "dma_totstkcnt=body",
        isProcessMsg : false
    };

    dma_totstkcnt.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : dma_search.get("isuCd") });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return;

    // 원본은 dts_Mst 를 이 응답으로 통째로 바꿨다 — initItem 이 먼저 비우므로 두 값만 옮기면 결과가 같다(§8 #10)
    dma_detail.set("parval", dma_totstkcnt.get("parval"));
    dma_detail.set("listShrs", dma_totstkcnt.get("listShrs"));
};

/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장폐지 이력 목록 조회 — 총건수를 표시한다. (원본 fn_list_sync + dts_List OnLoadCompleted — §5.2)
 * @returns {Promise<Boolean>} 조회 성공 여부
 * @hidden N
 */
scwin.selectList = async function () {
    const sbmOptions = {
        id : "sbm_selectList",
        method : "get",
        action : "/api/listing/lstproc/warrant/delisting/select-list",
        target : "dlt_list=body",
        gridview : "grd_List",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : dma_search.get("isuCd") });
    if (result?.skipped) return false;    // 진행 중 조회가 있어 이번 호출은 건너뜀
    if (!result.responseJSON?.success) return false;

    panel_page.setValue(dlt_list.getRowCount());    // 원본 FillGridHeaderTotalCnt(rowcount, panel_page)
    return true;
};

/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상세 조회 — 업무처리번호로 읽고 상장폐지일로 버튼 상태를 정한다. (원본 fn_read_sync + dts_Mst OnLoadCompleted — §5.3, §6.6)
 * @param {String} bzProcsNo 읽을 건의 업무처리번호 (비면 조회하지 않음)
 * @returns
 * @hidden N
 */
scwin.selectDetail = async function (bzProcsNo) {
    if ($c.util.isEmpty(bzProcsNo)) return;

    const sbmOptions = {
        id : "sbm_selectDetail",
        method : "get",
        action : "/api/listing/lstproc/warrant/delisting/select-one",
        target : "dma_detail=body",
        isProcessMsg : false
    };

    // 행을 빠르게 바꿔 누르면 마지막 요청이 이긴다(가이드 §5 — 취소된 앞 요청의 reject 는 handleError 가 무시)
    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo }, null, { onDuplicate : "abort" });
    if (result?.skipped) return;
    if (!result.responseJSON?.success) return;

    // 응답을 받은 뒤에만 업무처리번호를 바꾼다 — 실패하면 이전 상태 그대로(§8 #6)
    scwin.bzProcsNo = bzProcsNo;
    scwin.applyButtonState();
    scwin.savedState = scwin.getEditState();
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 29
 * @description 등록(I)·수정(U). 화면 값으로 마스터(dma_save)와 종목 상세(dma_saveIsuDtl)를 만들어 보내고,
 * 성공하면 다시 조회한 뒤 그 건을 상세로 읽는다. (원본 fn_trs + trs_Save OnSuccess/OnFail — §5.4, §5.5)
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @returns
 * @hidden N
 */
scwin.saveTrs = async function (trJob) {
    const jobNm = scwin.JOB_NM[trJob] ?? "";

    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : (trJob === "I") ? "/api/listing/lstproc/warrant/delisting/register"
                                 : "/api/listing/lstproc/warrant/delisting/modify",
        target : "dma_saveResult=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    // 마스터 — 상세의 같은 이름 키를 옮기고 업무처리번호(수정만 — 등록은 서버 채번)·발행기관·증권그룹을 채운다(원본 fn_trs 의 dts_Mst)
    dma_save.setEmptyValue();
    const detail = dma_detail.getJSON();
    Object.keys(dma_save.getJSON()).forEach(key => {
        if (key in detail) dma_save.set(key, detail[key] ?? "");
    });
    dma_save.set("bzProcsNo", (trJob === "U") ? scwin.bzProcsNo : "");
    dma_save.set("isurCd", scwin.isurCd);
    dma_save.set("secugrpId", scwin.secugrpId);
    // TODO: 원본이 보내던 MKTACT_APPL_OBJ_TP_CD("1" 종목별)·LIST_BZ_TP_CD(203/204 — 명세상 서버가 secugrpId 로 분기)·TRS_IDX·DIV_IDX·COUNT 는 명세 요청에 없어 보내지 않는다 (§10 #3)

    // 종목 상세 — 원본 dts_Isu(한 행: BZ_PROCS_NO·ISU_CD). 상장증권수·액면가는 총주식수 조회·상세 값
    // TODO: 발행가격(isuPrc)은 화면에 출처가 없어 비워 보낸다 (§10 #4)
    dma_saveIsuDtl.setEmptyValue();
    dma_saveIsuDtl.set("isuCd", dma_search.get("isuCd"));
    dma_saveIsuDtl.set("listShrs", dma_detail.get("listShrs"));
    dma_saveIsuDtl.set("parval", dma_detail.get("parval"));

    // 명세 requestData — isuDtl 은 명세가 getAllJSON()(배열)이라 한 건 배열로 보낸다(§5 차이 #3)
    const requestData = {
        ...dma_save.getJSON(),
        isuDtl : [dma_saveIsuDtl.getJSON()]
    };

    dma_saveResult.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!await scwin.checkResult(result, jobNm)) return;

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", jobNm));

    // 등록은 서버가 채번한 번호(응답 bzProcsNo), 수정은 고른 건 — 다시 조회한 뒤 그 건을 상세로 읽는다(원본 OnSuccess 의 fn_read_sync)
    const savedNo = (trJob === "I") ? String(dma_saveResult.get("bzProcsNo") ?? "") : scwin.bzProcsNo;
    if (!await scwin.reload()) return;
    await scwin.openSavedDetail(savedNo);
};

/**
 * @method
 * @name scwin.removeTrs
 * @author Inswave
 * @date 2026. 10. 29
 * @description 삭제. 업무처리번호·증권그룹을 dma_delete 로 보내고, 성공하면 신규 상태로 되돌려 다시 조회한다.
 * (원본 fn_trs(TRS_IDX_DELETE) + trs_Save OnSuccess — §5.6)
 * @returns
 * @hidden N
 */
scwin.removeTrs = async function () {
    const sbmOptions = {
        id : "sbm_removeTrs",
        method : "post",
        action : "/api/listing/lstproc/warrant/delisting/remove",
        ref : "dma_delete",
        target : "dma_saveResult=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    // TODO: 명세 dma_delete 키 표가 깨져 있다 — bzProcsNo·secugrpId 로 읽었다 (§5 차이 #4, §10 #2)
    dma_delete.setEmptyValue();
    dma_delete.set("bzProcsNo", scwin.bzProcsNo);
    dma_delete.set("secugrpId", scwin.secugrpId);

    dma_saveResult.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!await scwin.checkResult(result, "삭제")) return;

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    await scwin.reload();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.getSecugrpId
 * @author Inswave
 * @date 2026. 10. 29
 * @description 메뉴 코드로 증권그룹ID 를 정한다. 메뉴 STF05707 이면 신주인수권증권(SW), 그 밖(이 화면 메뉴 STF05806)은 신주인수권증서(SR).
 * (원본 fn_getSecuGrpId(InfoMenuID()) — 업무공통 표 STF05707 → SW, STF05806 → SR, §3)
 * @returns {String} 증권그룹ID
 * @hidden N
 */
scwin.getSecugrpId = function () {
    const menuInfo = $c.data.getParameter("menuInfo") ?? {};
    return String(menuInfo.menuCode ?? "").endsWith(scwin.MENU_CD_SW) ? $c.lc.glb.SECUGRP_ID_SW : $c.lc.glb.SECUGRP_ID_SR;
};

/**
 * @method
 * @name scwin.setSecugrpLabel
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장증권수 라벨·그리드 머리글 — 신주인수권증권(SW)은 "상장증권수", 신주인수권증서(SR)는 "상장증서수". (원본 fn_list_sync 앞부분 — §6.1)
 * @returns
 * @hidden N
 */
scwin.setSecugrpLabel = function () {
    const label = (scwin.secugrpId === $c.lc.glb.SECUGRP_ID_SR) ? "상장증서수" : "상장증권수";
    lb_LIST_SHRS.setValue(label);
    grd_List.setHeaderValue("h_listShrs", label);
};

/**
 * @method
 * @name scwin.setComponentByMkt
 * @author Inswave
 * @date 2026. 10. 29
 * @description 시장구분별 입력 방식. 유가(1)는 상장폐지사유를 찾기로만 고르고 예고기간·정리매매 허용기간을 보인다.
 * 코스닥(2)은 사유를 직접 입력하고 두 기간 행을 숨긴다. 그 밖의 값이면 바꾸지 않는다. (원본 fn_initMktPerComponent — §6.2)
 * @param {String} mktTpCd 시장구분 1: 유가, 2: 코스닥
 * @returns
 * @hidden N
 */
scwin.setComponentByMkt = function (mktTpCd) {
    if (mktTpCd !== "1" && mktTpCd !== "2") return;

    const isKse = (mktTpCd === "1");
    img_DELIST_RSN_DSC.setDisabled(!isKse);
    txb_DELIST_RSN_DSC.setReadOnly(isKse);
    [tr_DELIST_ADVNOTI, tr_ARRANTRD].forEach(comp => {
        if (isKse) {
            comp.show("");
        } else {
            comp.hide();
        }
    });
};

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 10. 29
 * @description 조회 — 종목이 없으면 안내, 있으면 신규 상태로 되돌려 총주식수·이력을 다시 조회한다. (원본 btn_Search onclick — §6.3)
 * @returns
 * @hidden N
 */
scwin.search = async function () {
    if ($c.util.isEmpty(dma_search.get("isuCd"))) {
        await $c.win.alert("[종목]을 선택하세요.");
        txb_ISU_CD.focus();
        return;
    }
    await scwin.reload();
};

/**
 * @method
 * @name scwin.reload
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 상태로 되돌린 뒤 총주식수 → 이력 순서로 조회한다.
 * (원본 fn_initItem + fn_isubook_read_sync + fn_list_sync — 종목 선택·조회·저장/수정/삭제 성공 뒤 — §6.4)
 * @returns {Promise<Boolean>} 이력 조회 성공 여부
 * @hidden N
 */
scwin.reload = async function () {
    scwin.initItem();
    await scwin.selectTotStkCnt();
    return await scwin.selectList();
};

/**
 * @method
 * @name scwin.initItem
 * @author Inswave
 * @date 2026. 10. 29
 * @description 입력 초기화 — 버튼 신규 상태, 상세 비우기, 업무처리번호 비우기. 통신 없음. (원본 fn_initItem — §6.5)
 * @returns
 * @hidden N
 */
scwin.initItem = function () {
    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
    dma_detail.setEmptyValue();
    scwin.bzProcsNo = "";
    scwin.savedState = "";
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description 종목 찾기. 증권그룹 종목(ULDSTF92017)을 골라 조회 영역에 채우고, 종목 시장으로 입력 방식을 바꾼 뒤 다시 조회한다.
 * 취소·닫기면 아무것도 하지 않는다. (원본 img_ISU_NM onclick + fn_GetParIsuCd + fn_SetParIsuCd + fn_PopFindIsu — §6.7)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    // AS-IS arr[0]·arr[1] "" (검색어 없음), arr[2] 증권그룹ID → pcc 는 secugrpId 만 넘긴다
    const result = await $c.lc.popFindIsu(scwin.secugrpId);
    // 취소·닫기(X)도 { isCloseButtonClick } 객체가 온다 → 종목코드로 판정(원본 DBCLICKYN "Y" 일 때만 반영)
    if (result?.isCloseButtonClick === true || $c.util.isEmpty(result?.isuCd)) return;

    dma_search.set("isuCd", result.isuCd);
    dma_search.set("isuNm", result.isuKorNm ?? "");
    scwin.mktTpCd = String(result.spotIsuTrdMktTpCd ?? "");
    scwin.isurCd = String(result.isurCd ?? "");

    scwin.setComponentByMkt(scwin.mktTpCd);
    await scwin.reload();
};

/**
 * @method
 * @name scwin.openRsnPopup
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장폐지사유 찾기(ULDSTF92008). 고른 사유 코드·사유·근거규정을 상세에 채운다. 취소·닫기면 아무것도 하지 않는다.
 * (원본 img_DELIST_RSN_DSC onclick + fn_GetParRsn/fn_SetParRsn + fn_PopFindClssLstRsnCd — §6.8)
 * @returns
 * @hidden N
 */
scwin.openRsnPopup = async function () {
    // AS-IS arr[0] "1"(유가), arr[1] "05" → 92008 수신 키 mkt·rsn
    const res = await $c.lc.popFindClssLstRsnCd(scwin.RSNCD_DELIST, { mkt : "1", rsn : "05" });
    if (res?.isCloseButtonClick === true || $c.util.isEmpty(res?.code)) return;    // 취소·닫기

    dma_detail.set("delistRsnCd", res.code);
    dma_detail.set("delistRsnDsc", res.name ?? "");
    dma_detail.set("grndRegulNm", res.regl ?? "");
};

/**
 * @method
 * @name scwin.applyButtonState
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상세를 읽은 뒤 버튼 상태. 업무처리번호가 없으면 insert, 상장폐지일이 오늘 이후(오늘 포함)면 update, 지났으면 error(기안만).
 * (원본 dts_Mst OnLoadCompleted — cGetToday <= DELIST_DD, §6.6)
 * @returns
 * @hidden N
 */
scwin.applyButtonState = function () {
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
        return;
    }
    const isFuture = ($c.date.getServerDateTime("yyyyMMdd") <= String(dma_detail.get("delistDd") ?? ""));
    $c.util.setButtonState("grpBtnBox", isFuture ? "update" : "error", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.getEditState
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상세 입력값의 현재 상태 문자열 — 읽은 직후 값과 비교해 바뀌었는지 본다. (원본 dts_Mst.IsUpdated — §6.13)
 * @returns {String} 상세 입력값 JSON 문자열
 * @hidden N
 */
scwin.getEditState = function () {
    return JSON.stringify(dma_detail.getJSON());
};

/**
 * @method
 * @name scwin.getListBzTpCd
 * @author Inswave
 * @date 2026. 10. 29
 * @description 상장업무구분코드 — 신주인수권증권(SW) 203, 신주인수권증서(SR) 204 상장폐지. (원본 fn_getListBzTpCd — §6.9)
 * @returns {String} 상장업무구분코드
 * @hidden N
 */
scwin.getListBzTpCd = function () {
    if (scwin.secugrpId === $c.lc.glb.SECUGRP_ID_SW) return $c.lc.glb.LIST_BZ_TP_CD_203;
    if (scwin.secugrpId === $c.lc.glb.SECUGRP_ID_SR) return $c.lc.glb.LIST_BZ_TP_CD_204;
    return "";
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 29
 * @description 저장·수정 전 입력 검증. 원본 fn_CheckForm 순서를 따른다 — 필수는 원본 문구로, byte 길이는 공통 검증(validateDataCollect)으로,
 * 끝에 서버 업무 중복 입력 확인을 둔다. (§6.10)
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    const isuCd = dma_search.get("isuCd");
    const delistDd = String(dma_detail.get("delistDd") ?? "");

    // 1) 종목
    if ($c.util.isEmpty(isuCd)) {
        await $c.win.alert("[종목코드]를 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }

    // 2) 상장폐지일 필수 · 현재일 이후 (원본 cGetToday >= DELIST_DD 면 실패 — 클라이언트 시각 → 서버 시각)
    if ($c.util.isEmpty(delistDd)) {
        await $c.win.alert("[상장폐지일]을 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }
    if ($c.date.getServerDateTime("yyyyMMdd") >= delistDd) {
        await $c.win.alert("[상장폐지일]을 현재일이후로 입력하세요.");
        edt_DELIST_DD.focus();
        return false;
    }

    // 3) 상장폐지사유 — 유가는 찾기로 고른 코드, 코스닥은 직접 입력(2000 byte)
    if (scwin.mktTpCd === "1") {
        if ($c.util.isEmpty(dma_detail.get("delistRsnCd"))) {
            await $c.win.alert("[상장폐지사유]를 선택하세요.");
            txb_DELIST_RSN_DSC.focus();
            return false;
        }
    } else if (scwin.mktTpCd === "2") {
        if ($c.util.isEmpty(dma_detail.get("delistRsnDsc"))) {
            await $c.win.alert("[상장폐지사유]를 입력하세요.");
            txb_DELIST_RSN_DSC.focus();
            return false;
        }
        const rsnOptions = {
            validateType : "alert",
            checkType : "single",
            fields : {
                txb_DELIST_RSN_DSC : { maxLengthB : 2000, name : "상장폐지사유" }
            }
        };
        if (!await $c.validate.validateDataCollect(panel_Item, rsnOptions)) return false;
    }

    // 4) 근거규정 필수 · 200 byte
    if ($c.util.isEmpty(dma_detail.get("grndRegulNm"))) {
        await $c.win.alert("[근거규정]을 입력하세요.");
        txb_GRND_REGUL_NM.focus();
        return false;
    }
    const grndOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            txb_GRND_REGUL_NM : { maxLengthB : 200, name : "근거규정" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_Item, grndOptions)) return false;

    // 5) 업무 중복 입력 확인 — 종목·상장폐지일·업무처리번호(신규는 빈 값)·상장업무구분 203/204
    // TODO: pcc checkBzDoubleInput 은 주식 변경상장 경로(stock/chglisting/check-double-input)이고 명세에 없다 — 203/204 업무에서도 맞는지 확인 (§5.7, §10 #5)
    // TODO: pcc 결함 (§10 #5, 배포 전 차단) — 응답에 disclsProcsDdtm 이 없으면(undefined) 중복으로 보고 false 라 저장·수정이 늘 막힌다.
    //       skipped 가드도 없다 — pcc 수정 요청
    return await $c.lc.checkBzDoubleInput(isuCd, delistDd, scwin.bzProcsNo, scwin.getListBzTpCd());
};

/**
 * @method
 * @name scwin.checkResult
 * @author Inswave
 * @date 2026. 10. 29
 * @description 등록·수정·삭제 응답 판정. 통신 실패이거나 completeYn(boolean)이 와서 true 가 아니면 MSG-A002 를 안내하고 false.
 * register·remove 는 명세에 응답 정의가 없어 completeYn 이 오지 않으면 success 만으로 판정한다. (§5.4~5.6)
 * @param {Object} result executeDynamic 결과
 * @param {String} jobNm 처리명 (저장·수정·삭제)
 * @returns {Promise<Boolean>} 성공 여부
 * @hidden N
 */
scwin.checkResult = async function (result, jobNm) {
    // 명세: completeYn 는 boolean — dataMap(text) 을 거치지 않고 응답 body 에서 바로 본다
    // TODO: register·remove 응답 구조는 가정 — 명세 확인 필요 (§10 #1)
    const completeYn = result.responseJSON?.body?.completeYn;
    const completed = (completeYn === undefined || completeYn === null || String(completeYn) === "true");
    if (result.responseJSON?.success === true && completed) return true;

    await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));
    return false;
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규 저장. 검증 → 확인 → 등록 순서. 업무처리번호는 등록 API 가 채번한다(명세). (원본 fn_save — §6.11, §1.4 업무 6)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    // 원본 fn_getNewBzProcNo(dts_BzProcsNo) 화면 채번 + 14자리 검사는 없앴다 — 명세 register 가 서버 채번(§5.8)
    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 29
 * @description 수정. 검증 → 확인 → 수정 순서 (원본 fn_update — §6.11, §1.4 업무 7). 원본은 변경 여부를 확인하지 않는다.
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 29
 * @description 삭제. 확인을 받은 뒤 삭제한다. 입력 검증은 하지 않는다. (원본 fn_delete — §6.11, §1.4 업무 8)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.removeTrs();
};

/**
 * @method
 * @name scwin.openSavedDetail
 * @author Inswave
 * @date 2026. 10. 29
 * @description 저장·수정 성공 뒤 다시 조회한 이력에서 그 건을 찾아 상세로 읽는다. 찾지 못하면 원본처럼 마지막 행을 읽는다.
 * (원본 trs_Save OnSuccess 의 fn_read_sync(dts_List.CountRow) — §6.12, §8 #4)
 * @param {String} bzProcsNo 저장·수정한 건의 업무처리번호
 * @returns
 * @hidden N
 */
scwin.openSavedDetail = async function (bzProcsNo) {
    const rowCount = dlt_list.getRowCount();
    if (rowCount === 0) return;

    let rowIndex = rowCount - 1;
    for (let i = 0; i < rowCount; i++) {
        if (String(dlt_list.getCellData(i, "bzProcsNo") ?? "") === bzProcsNo) {
            rowIndex = i;
            break;
        }
    }
    await scwin.selectDetail(String(dlt_list.getCellData(rowIndex, "bzProcsNo") ?? ""));
};

/**
 * @method
 * @name scwin.getDsclFormCd
 * @author Inswave
 * @date 2026. 10. 29
 * @description 공시안내문 서식코드. 유가 SW 68913·SR 68917, 코스닥 SW 70925·SR 70930. (원본 fn_dscl 의 arr[0] — §6.13)
 * @returns {String} 서식코드 (시장구분이 1·2 가 아니면 빈 문자열)
 * @hidden N
 */
scwin.getDsclFormCd = function () {
    return String(scwin.DSCL_FORM_CD[scwin.mktTpCd]?.[scwin.secugrpId] ?? "");
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 29
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 fn_GetPar 로 채우던 arr[0..3] 과 마스터(코스닥은 영문 마스터도)다. (§6.13)
 * @returns {Object} 넘길 data (서식코드를 정할 수 없으면 null)
 * @hidden N
 */
scwin.getDsclData = function () {
    const formCd = scwin.getDsclFormCd();
    if ($c.util.isEmpty(formCd)) return null;

    const mst = dma_detail.getJSON();
    return {
        formCd : formCd,                                    // AS-IS arr[0]
        bzProcsNo : scwin.bzProcsNo,                        // AS-IS arr[1]
        isurCd : scwin.isurCd,                              // AS-IS arr[2]
        mktId : scwin.mktTpCd,                              // AS-IS arr[3]
        isu : [],                                           // AS-IS 종목 복사는 주석 처리돼 있었다
        mst : [mst],                                        // AS-IS CopyDataSet(dts_Mst, param_dts_mst)
        isuEng : [],
        mstEng : (scwin.mktTpCd === "2") ? [mst] : []       // AS-IS 코스닥만 CopyDataSet(dts_Mst_Eng, …) — dts_Mst_Eng 는 dts_Mst 사본
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 29
 * @description 공시안내문작성 팝업을 data 로 넘겨 열고 닫힐 때까지 기다린다. 상세를 고친 뒤 저장하지 않았으면 안내만 한다. (원본 fn_dscl — §6.13, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.writeDscl = async function () {
    // MSG-0022 "변경된 항목이 있습니다. 수정후에 안내문작성을 다시 클릭하세요."
    if (scwin.getEditState() !== scwin.savedState) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }

    const data = scwin.getDsclData();
    if (!data) {
        // TODO: 시장구분 1·2 외 처리·문구는 가정 — 원본은 이전 fn_GetPar 그대로 열었다 (§8 #8, §10 #8)
        await $c.win.alert("안내문을 작성할 수 없는 시장구분입니다.");
        return;
    }

    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 735,
        height : 815,
        type : "pageFramePopup"
    };

    // TODO: 경로는 가정, 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10 #8). 원본은 닫힌 뒤 다시 조회하지 않는다.
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, data);
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 29
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.13, §10 #8, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행회사코드 [3] 시장구분 을 채운다
 * @param {Object} dltIsu 92024 의 종목 dataList
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @param {Object} dlt2 92024 의 원천 자료 2 (쓰지 않음)
 * @param {Object} dlt3 92024 의 원천 자료 3 (쓰지 않음)
 * @param {Object} dlt4 92024 의 원천 자료 4 (쓰지 않음)
 * @param {Object} dltIsuEng 92024 의 영문 종목 dataList
 * @param {Object} dltMstEng 92024 의 영문 마스터 dataList
 * @returns {Number} arr 길이
 * @hidden N
 */
scwin.getPar = function (arr, dltIsu, dltMst, dlt2, dlt3, dlt4, dltIsuEng, dltMstEng) {
    const data = scwin.getDsclData();
    if (!data) return arr.length;

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;

    scwin.fillDataList(dltIsu, data.isu);
    scwin.fillDataList(dltMst, data.mst);
    scwin.fillDataList(dltIsuEng, data.isuEng);
    scwin.fillDataList(dltMstEng, data.mstEng);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 29
 * @description 컬럼 정의가 비어 있는 다른 화면의 dataList 에 행을 채운다. setJSON 은 선언된 컬럼만 옮기므로 첫 행의 키로 컬럼을 먼저 만든다.
 * (92024 의 원천 자료 dataList 는 서식마다 컬럼이 달라 부모가 컬럼째 넘긴다 — 원본 CopyDataSet)
 * @param {Object} dataList 채울 dataList (없으면 무시)
 * @param {Array} rows 넣을 행 목록
 * @returns
 * @hidden N
 */
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};

/**
 * @method
 * @name scwin.writeDraft
 * @author Inswave
 * @date 2026. 10. 29
 * @description 기안문작성 팝업을 고른 건의 업무처리번호와 함께 열고 닫힐 때까지 기다린다. (원본 fn_drft + fn_PopFindDraft — §6.14)
 * pcc $c.lc.popFindDraft 는 값을 넘기지 않는 콜백형이라 쓰지 않는다.
 * @returns
 * @hidden N
 */
scwin.writeDraft = async function () {
    // 원본은 이력 첫 행(NameValue(1, …))의 번호를 넘겼다 — 기안은 상세를 고른 뒤에만 켜지므로 고른 건으로 고친다(§8 #7)
    if ($c.util.isEmpty(scwin.bzProcsNo)) return;

    const options = {
        id : "ULDSTF92004",
        popupName : "기안문작성",
        width : 888,
        height : 730,
        type : "pageFramePopup"
    };

    // TODO: 기안 팝업 전환본이 없어 경로·수신 키(bzProcsNo)는 가정 (§10 #8)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92004.xml", options, { bzProcsNo : scwin.bzProcsNo });
};
